/** cPanel WHM Compiler Access in the approved Compiler lock card; the sec client paints it from GET /api/server/sec/compiler-access. */
const compilerAccess = (v: View): string => {
  const canRead = v.root
  const fact = (key: string, label: Copy): string => `<div class="xp-whm-detail-field"><dt>${v.text(label)}</dt><dd><bdi data-sec-field="${key}">${v.text(unavailable)}</bdi></dd></div>`
  const body = `<label class="xp-whm-detail-choice"><input type="checkbox" data-sec-input="restricted" disabled><span>${v.text(msgid('Restrict compiler access'))}</span></label>`
    + `<dl class="xp-whm-detail-fields">${fact('restriction', msgid('Compilers'))}${fact('host-state', msgid('Host state'))}${fact('commands', msgid('Restricted commands'))}${fact('group', msgid('Compiler group'))}${fact('hook', msgid('Re-apply after package updates'))}${fact('updated', msgid('Last saved (UTC)'))}${fact('reconcile', msgid('Last apply request'))}${fact('observed-at', msgid('Observed at (UTC)'))}</dl>`
    + table(v, msgid('Compiler exceptions'), [msgid('Account'), msgid('Reason')], [], unavailable).replace('<tbody>', '<tbody data-sec-rows="exceptions">')
    + `<div class="xp-whm-detail-field"><label for="whm-detail-compiler-exception-account">${v.text(msgid('Account'))}</label><select id="whm-detail-compiler-exception-account" data-sec-input="account" aria-describedby="whm-detail-compiler-exception-help" disabled><option value="">${v.text(msgid('Select an account'))}</option></select><p class="xp-help" id="whm-detail-compiler-exception-help">${v.text(msgid('Accounts on a jailed shell stay restricted and cannot be added. Change the shell of the account or its plan first.'))}</p></div>`
    + actions(button(v, msgid('Add account'), 'data-sec-action="grant"', true) + button(v, msgid('Remove exception'), 'data-sec-action="revoke"', true) + button(v, msgid('Refresh'), 'data-sec-action="refresh"', !canRead))
    + `<p class="xp-whm-detail-status" data-sec-status data-state="${canRead ? 'unread' : 'unavailable'}" role="status">${v.text(canRead ? msgid('Nothing has been read yet.') : msgid('This page requires an authorized administrator. Nothing was read or changed.'))}</p><p class="xp-whm-detail-status" data-sec-result role="status" hidden></p>`
  return card(v, 'panel-compiler', msgid(msgctxt('approved-xwhm', 'Compiler lock')), body)
    .replace('<section class="xp-whm-detail-card"', `<section class="xp-whm-detail-card" data-sec-workspace data-sec-page="compiler-access" data-sec-can-read="${canRead}" data-sec-can-manage="${canRead && !v.readOnly}"`)
}
// WHM cPHulk, Password Strength Configuration and session lifetimes, painted by the sign-in policy client from GET /api/server/sec/sign-in.
const signInPolicy = (v: View): string => {
  const canRead = v.root && !v.readOnly
  const control = (key: string, label: Copy, extra = ' min="1"', textarea = false): string => {
    const id = `whm-sign-in-${key.replaceAll('.', '-')}`
    return `<div class="xp-whm-detail-field"><label for="${id}">${v.text(label)}</label>${textarea ? `<textarea id="${id}" data-sign-in-field="${key}" rows="4" dir="ltr" disabled></textarea>` : `<input id="${id}" type="number" data-sign-in-field="${key}" dir="ltr"${extra} disabled>`}</div>`
  }
  const services = [['panel', msgid('Panel sign-in')], ['mail', msgid('Email accounts')], ['ftp', msgid('FTP accounts')], ['database', msgid('Database users')], ['webdisk', msgid('Web Disk')], ['directory', msgid('Protected directories')]] as const
  const lockout = `<p>${v.text(msgid('Counts reset after a successful sign-in. A lock never ends a session that is already open.'))}</p><h3>${v.text(msgid('By username'))}</h3><div class="xp-whm-detail-fields">${control('lockout.username.attempts', msgid('Failed attempts'))}${control('lockout.username.windowMin', msgid('Within, minutes'))}${control('lockout.username.durationMin', msgid('Lock the username for, minutes'))}</div>`
    + table(v, msgid(msgctxt('approved-xwhm', 'Locked right now')), [msgid('Username or address'), msgid('Failed attempts'), msgid('Until (UTC)')], [], unavailable).replace('<tbody>', '<tbody data-sign-in-lockouts>')
    + `<div class="xp-whm-detail-field"><label for="whm-sign-in-unlock-target">${v.text(msgid('Lock to lift'))}</label><select id="whm-sign-in-unlock-target" data-sign-in-unlock-target disabled></select></div>`
    + actions(button(v, msgid('Unlock username'), 'data-sign-in-unlock="username"', true) + button(v, msgid('Unblock address'), 'data-sign-in-unlock="ip"', true)) + `<p>${v.text(msgid('Every lock and unlock is written to the audit log.'))}</p>`
  const addresses = `<div class="xp-whm-detail-fields">${control('lockout.ip.attempts', msgid('Failed attempts'))}${control('lockout.ip.windowMin', msgid('Within, minutes'))}${control('lockout.ip.durationMin', msgid('Block the address for, minutes'))}</div>`
    + `<div class="xp-whm-detail-fields">${control('lockout.ipAllow', msgid('Addresses never locked, one per line'), '', true)}${control('lockout.ipDeny', msgid('Addresses always refused, one per line'), '', true)}</div><p>${v.text(msgid('Addresses on the never-locked list are not counted or locked. A locked or refused address is turned away by the panel sign-in; it is not added to the firewall.'))}</p>`
  const passwords = `<p>${v.text(msgid('A new password must reach the required strength, from 0 to 100; values round up to a multiple of 5. Leave a service empty to use the default. Existing passwords are not checked.'))}</p><div class="xp-whm-detail-fields">${control('passwordStrength.default', msgid('Default required strength'), ' min="0" max="100"')}${services.map(([service, label]) => control(`passwordStrength.perService.${service}`, label, ' min="0" max="100"')).join('')}</div>`
    + `<h3>${v.text(msgid('Sessions'))}</h3><div class="xp-whm-detail-fields">${control('session.idleMin', msgid('Idle timeout, minutes'), ' min="1" max="30"')}${control('session.absoluteHours', msgid('Session lifetime, hours'), ' min="1" max="24"')}</div><p>${v.text(msgid('Sessions end after at most 30 idle minutes and 24 hours in any case; shorter values apply to every panel sign-in.'))}</p>`
    + actions(button(v, msgid('Save sign-in policy'), 'data-sign-in-save', true, true) + button(v, msgid('Refresh'), 'data-sign-in-refresh', !canRead))
    + `<p class="xp-whm-detail-status" data-sign-in-status data-state="${canRead ? 'unread' : 'unavailable'}" role="status">${v.text(canRead ? msgid('Nothing has been read yet.') : msgid('This page requires an authorized administrator. Nothing was read or changed.'))}</p>`
  return `<div class="xp-whm-detail-column" data-sign-in-policy data-sign-in-can-read="${canRead}" data-sign-in-can-manage="${canRead}">${card(v, 'panel-lockout', msgid('Sign-in lockout'), lockout)}${card(v, 'panel-ip-lockout', msgid('By IP address'), addresses)}${card(v, 'panel-passwords', msgid('Password strength and sessions'), passwords)}</div>`
}
const panelSecurity = (v: View): string => workspace(v, '/whm/security', msgid('Panel security'), msgid('Access policy, optional multi-factor authentication and host protections.'), card(v, 'security-evidence', msgid('Observed security evidence'), renderWhmSecurityEvidence({ locale: v.locale })) + card(v, 'panel-access', msgid('Access'), `<div class="xp-whm-detail-fields">${field(v, 'panelPort', msgid('Panel port'), { type: 'number', disabled: true, value: v.props.serverSettings?.panelPort })}${choice(v, 'entrance-path-enabled', msgid('Enable secret entrance path'), undefined)}${field(v, 'secret-entrance', msgid(msgctxt('approved-xwhm', 'Secret entrance path')), { disabled: true })}</div>${actions(button(v, msgid('Regenerate entrance path'), '', true))}${choice(v, 'panel-allowlist-enabled', msgid('Enable IP allowlist'), undefined)}${field(v, 'panel-allowlist', msgid(msgctxt('approved-xwhm', 'Addresses and ranges, one per line')), { type: 'textarea', disabled: true })}${status(v)}`) + signInPolicy(v) + card(v, 'panel-tokens', msgid(msgctxt('approved-xwhm', 'API tokens')), `<div class="xp-whm-detail-fields">${field(v, 'token-name', msgid('Name'), { disabled: true })}${field(v, 'token-addresses', msgid('Allowed addresses'), { type: 'textarea', disabled: true })}${field(v, 'token-expiry', msgid(msgctxt('approved-xwhm', 'Expires')), { type: 'date', disabled: true })}</div>${choice(v, 'token-no-expiry', msgid(msgctxt('approved-xwhm', 'No expiry')), undefined)}<h3>${v.text(msgid('Scopes'))}</h3><div class="xp-whm-detail-choice-grid">${['accounts:read', 'accounts:write', 'plans:read', 'dns:write', 'backups:read', 'transfer:read', 'metrics:read'].map(scope => choice(v, `token-scope-${scope}`, scope, undefined)).join('')}</div>${actions(button(v, msgid('Cancel'), '', true) + button(v, msgid(msgctxt('approved-xwhm', 'Create token')), '', true))}${table(v, msgid('Current API tokens'), [msgid('Name'), msgid('Scopes'), msgid('Allowed addresses'), msgid(msgctxt('approved-xwhm', 'Expires')), msgid('Last used (UTC)'), msgid(msgctxt('approved-xwhm', 'Manage'))], [])}${actions(button(v, msgid('Revoke token'), '', true))}${status(v)}`), card(v, 'panel-mfa', msgid('Two-factor for root'), `<p>${v.text(msgid('Enrollment is optional. Existing authentication factors are preserved; development does not force enrollment.'))}</p><a class="xp-btn" href="/whm/security/sign-in">${v.text(msgid('Password and authenticator'))}</a>`) + card(v, 'panel-waf', msgid('Nginx web application firewall'), `<div class="xp-whm-detail-fields">${field(v, 'requests-per-address', msgid('Requests per address'), { type: 'number', disabled: true })}${field(v, 'burst', msgid('Burst'), { type: 'number', disabled: true })}${field(v, 'body-size', msgid(msgctxt('approved-xwhm', 'Largest request body')), { disabled: true })}</div>${choice(v, 'waf-request-unlimited', msgid('Unlimited request rate'), undefined)}${choice(v, 'waf-burst-unlimited', msgid('Unlimited burst'), undefined)}${choice(v, 'waf-body-unlimited', msgid('Unlimited request body'), undefined)}<div class="xp-whm-detail-fields">${field(v, 'denied-addresses', msgid('Denied addresses and ranges'), { type: 'textarea', disabled: true })}${field(v, 'denied-paths', msgid('Path patterns'), { type: 'textarea', disabled: true })}${field(v, 'denied-user-agents', msgid(msgctxt('approved-xwhm', 'User-agent patterns')), { type: 'textarea', disabled: true })}${field(v, 'denied-response', msgid(msgctxt('approved-xwhm', 'Answer for denied requests')), { disabled: true, choices: [['403', msgid('403 Forbidden')], ['444', msgid('Close without a response')]] })}</div>${status(v)}`) + card(v, 'panel-dangerous-php', msgid('Dangerous PHP functions'), `<p>${v.text(msgid('Global function policy and per-account exceptions have not been read. A listed function is not a verified prohibition.'))}</p><div class="xp-whm-detail-choice-grid">${['exec', 'shell_exec', 'system', 'passthru', 'proc_open', 'popen'].map(name => choice(v, `php-function-${name}`, name, undefined)).join('')}</div>${table(v, msgid('PHP function exceptions'), [msgid('Account'), msgid('Functions'), msgid('Reason')], [])}${actions(button(v, msgid('Add exception'), '', true))}${status(v)}`) + compilerAccess(v) + card(v, 'panel-apply', msgid('Review policy changes'), `${actions(button(v, msgid('Discard'), '', true) + button(v, msgid('Save and apply'), '', true, true))}${status(v, msgid('No global host-policy write or reviewed draft is connected here. Existing password and optional-factor settings use their own authenticated workflow.'))}`))

