  const phpLayoutStyles = `<style>.xp-whm-detail[data-whm-detail-route="/whm/software/php"] .xp-php-versions{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,236px),1fr));gap:16px}.xp-whm-detail[data-whm-detail-route="/whm/software/php"] .xp-php-version-card{display:flex;flex-direction:column;gap:24px;padding:24px;border:1px solid var(--xp-border);border-radius:12px;background:var(--xp-bg-surface);min-inline-size:0}.xp-whm-detail[data-whm-detail-route="/whm/software/php"] .xp-php-version-card__heading{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:8px}.xp-whm-detail[data-whm-detail-route="/whm/software/php"] .xp-php-version-card h3{font-size:18px;font-weight:600}.xp-whm-detail[data-whm-detail-route="/whm/software/php"] .xp-php-version-card [data-xp-slot="default-holder"]{padding:4px 10px;border-radius:999px;background:var(--xp-accent-soft);color:var(--xp-accent);font-size:12px;font-weight:600}.xp-whm-detail[data-whm-detail-route="/whm/software/php"] .xp-php-version-card .xp-whm-php-readback__facts{grid-template-columns:minmax(0,1fr)}.xp-whm-detail[data-whm-detail-route="/whm/software/php"] .xp-php-package-list{display:flex;flex-direction:column;gap:8px;min-inline-size:0;overflow-wrap:anywhere}.xp-whm-detail[data-whm-detail-route="/whm/software/php"] .xp-php-version-card__actions{display:flex;flex-wrap:wrap;gap:16px;margin-block-start:auto;padding-block-start:16px;border-block-start:1px solid var(--xp-border)}.xp-whm-detail[data-whm-detail-route="/whm/software/php"] :is(.xp-php-version-tabs,.xp-php-editor-tabs){display:flex;gap:4px;overflow-x:auto;border-block-end:1px solid var(--xp-border)}.xp-whm-detail[data-whm-detail-route="/whm/software/php"] :is(.xp-php-version-tabs,.xp-php-editor-tabs)>[role=tab]{flex:none;min-block-size:44px;padding:0 14px;border:0;border-block-end:2px solid transparent;border-radius:0;background:transparent;color:var(--xp-text-muted);font:inherit;cursor:pointer}.xp-whm-detail[data-whm-detail-route="/whm/software/php"] :is(.xp-php-version-tabs,.xp-php-editor-tabs)>[aria-selected=true]{border-block-end-color:var(--xp-accent);color:var(--xp-text);font-weight:600}.xp-whm-detail[data-whm-detail-route="/whm/software/php"] :is(.xp-php-config-group,[data-php-version-panel],[data-php-editor-modes],[role=tabpanel]){display:flex;flex-direction:column;gap:24px;min-inline-size:0}.xp-whm-detail[data-whm-detail-route="/whm/software/php"] .xp-php-config-split{display:grid;grid-template-columns:minmax(0,1.618fr) minmax(0,1fr);gap:24px;align-items:start}.xp-whm-detail[data-whm-detail-route="/whm/software/php"] :is(.xp-php-version-card,[data-php-editor-modes]) [hidden]{display:none}.xp-whm-detail[data-whm-detail-route="/whm/software/php"] .xp-php-extension-switch{display:flex;align-items:center;gap:8px;min-block-size:44px}.xp-whm-detail[data-whm-detail-route="/whm/software/php"] .xp-php-extension-switch input{inline-size:18px;block-size:18px;accent-color:var(--xp-accent)}@media(max-width:960px){.xp-whm-detail[data-whm-detail-route="/whm/software/php"] .xp-php-config-split{grid-template-columns:minmax(0,1fr)}}@media(max-width:640px){.xp-whm-detail[data-whm-detail-route="/whm/software/php"] .xp-php-version-card{padding:16px}}</style>`
  const extensions = `<div class="xp-whm-detail-fields">${field(pending, 'php-extension-version', msgid('Extensions for PHP version'), { choices: [] })}</div>${phpTable(msgid('Extensions per version'), [msgid(msgctxt('approved-xwhm', 'Extension')), msgid('Package'), msgid('Purpose'), msgid('Enabled')], [])}<div class="xp-whm-detail-choice-grid" data-php-extension-draft-grid>${['curl', 'gd', 'intl', 'mbstring', 'mysqli', 'opcache', 'pdo_mysql', 'zip'].map(name => choice(pending, `php-extension-${name}`, name, undefined)).join('')}</div>`
