export const whmDetailRoutes = Object.freeze(Object.keys(detailPages))

/** Full workspace structure survives unavailable host capabilities without exposing private records. */
export const renderWhmDetailPage = (input: DetailProps): string | undefined => {
  const route = input.activeRoute ?? '/whm'
  if (input.capabilityUnavailable && ['/whm/accounts', '/whm/accounts/new', '/whm/plans', '/whm/security/firewall', '/whm/services'].includes(route)) {
    // Read-only keeps the caller's scoped saved lists (their first page): closed rows and fields show saved values, disabled.
    const safe: DetailProps = { activeRoute: route, locale: input.locale, capabilityUnavailable: true, ...savedLists(input) }
    const v: View = { props: safe, locale: input.locale ?? 'en', readOnly: true, root: false, text: copy => escapeHtml(translator(input.locale)(copy)) }
    const { accounts, plans, resellers } = safe
    const planOf = (id: string) => plans?.find(plan => plan.id === id)
    const ownerOf = (id: string | null) => id === null ? 'root' : resellers?.find(reseller => reseller.id === id)?.username
    const statusText = (state: string) => v.text(state === 'active' ? msgid('Active') : state === 'suspended' ? msgid('Suspended') : msgid('Terminating'))
    const accountRows = (accounts ?? []).map(account => [`<input type="checkbox" value="${escapeHtml(account.username)}" disabled aria-label="${v.text(msgid('Select account'))} ${escapeHtml(account.username)}">`,
      renderLtrValue(account.username), renderLtrValue(account.primaryDomain), value(v, ownerOf(account.ownerId)), renderLtrValue(account.ipv4),
      planOf(account.planId) ? escapeHtml(planOf(account.planId)!.name) : v.text(unavailable), limitText(v, planOf(account.planId)?.resources.diskMb, 'MiB'),
      limitText(v, planOf(account.planId)?.resources.bandwidthMbMonth, 'MiB'), statusText(account.status), v.text(msgid('Read only'))])
    const owners: (readonly [string, string])[] = [['', 'root'], ...(resellers ?? []).map(reseller => [reseller.id, reseller.username] as const)]
    const accountList = card(v, 'account-list-unavailable', msgid('Accounts'), `<div class="xp-whm-detail-fields">${field(v, 'pending-account-search', msgid('Search accounts'))}${pick(v, 'pending-account-owner', msgid('Owner'), [['all', v.text(msgid('All owners'))], ...owners.map(([id, name]) => [id, escapeHtml(name)] as const)], 'all')}${pick(v, 'pending-account-plan', msgid('Plan'), [['all', v.text(msgid('All plans'))], ...(plans ?? []).map(plan => [plan.id, escapeHtml(plan.name)] as const)], 'all')}${pick(v, 'pending-account-status', msgid('Status'), [['all', v.text(msgid('All statuses'))], ['active', v.text(msgid('Active'))], ['suspended', v.text(msgid('Suspended'))]], 'all')}</div>${table(v, msgid('Accounts'), [msgid(msgctxt('approved-xwhm', 'Select')), msgid('Account'), msgid('Domain'), msgid('Owner'), 'IP', msgid('Plan'), msgid('Disk'), msgid(msgctxt('approved-xwhm', 'Bandwidth')), msgid('Status'), msgid('Actions')], accountRows, accounts ? msgid('No accounts.') : undefined)}${actions(button(v, msgid('Previous')) + button(v, msgid('Next')))}`)
    const creation = card(v, 'account-create-unavailable', msgid('Account identity and plan'), `<div class="xp-whm-detail-fields">${field(v, 'username', msgid('Username'), { id: 'new-acc-username' })}${field(v, 'primaryDomain', msgid('Primary domain'), { id: 'new-acc-domain' })}${field(v, 'contactEmail', msgid('Contact email'), { id: 'new-acc-contact', type: 'email' })}${pick(v, 'planId', msgid('Hosting plan'), (plans ?? []).map(plan => [plan.id, escapeHtml(plan.name)] as const), plans?.[0]?.id, 'new-acc-plan')}${field(v, 'password', msgid('Password'), { id: 'new-acc-password', type: 'password' })}${field(v, 'ipAssignment', msgid('IPv4 assignment'), { id: 'new-acc-ipv4', choices: [['shared', msgid('Default shared')]], value: 'shared' })}${field(v, 'ipv6', msgid('IPv6 address (optional)'), { id: 'new-acc-ipv6' })}</div>${renderApprovedWhmAccountCreateFields(safe)}${table(v, msgid('Selected plan capacity'), [msgid('Resource'), msgid('Plan'), msgid('After creation'), msgid('State')], [])}${actions(button(v, msgid('Create account'), '', true, true))}`)
    const shellText = (shell: string) => v.text(shell === 'jailed' ? msgid('Jailed shell') : msgid('No shell'))
    const planRows = (plans ?? []).map(plan => [escapeHtml(plan.name), `${limitText(v, plan.resources.diskMb, 'MiB')} / ${limitText(v, plan.resources.bandwidthMbMonth, 'MiB')}`,
      `${limitText(v, plan.resources.cpuPercent, '%')} / ${limitText(v, plan.resources.memoryMb, 'MiB')}`, `${limitText(v, plan.resources.ioReadBps, 'B/s')} / ${limitText(v, plan.resources.ioWriteBps, 'B/s')}`,
      limitText(v, plan.resources.maxProcesses), limitText(v, plan.caps.addonDomains), shellText(plan.shell), v.text(msgid('Read only'))])
    const planList = card(v, 'plans-unavailable', msgid('Hosting plans'), table(v, msgid('Hosting plans'), [msgid('Plan'), msgid('Disk / Bandwidth'), msgid('CPU / Memory'), msgid('Disk read / write'), msgid('Processes'), msgid('Addon domains'), msgid('Shell'), msgid('Actions')], planRows, plans ? msgid('No plans yet') : undefined) + actions(button(v, msgid('Create plan'))))
    // The editor shows the first saved plan of the list, disabled.
    const shown = plans?.[0]
    const limitField = (item: { key: string; label: Copy; scale: number }, saved: Limit | undefined) => field(v, `pending-plan-${item.key}`, item.label, { type: 'number', ...(typeof saved === 'number' ? { value: saved / item.scale } : {}) }) + choice(v, `pending-plan-unlimited-${item.key}`, msgid('Unlimited'), saved === undefined ? undefined : saved === 'unlimited')
    const planEditor = card(v, 'plan-editor-unavailable', msgid('Plan editor'), `<div class="xp-whm-detail-fields">${field(v, 'pending-plan-name', msgid('Plan name'), shown ? { value: shown.name } : {})}${pick(v, 'pending-plan-features', msgid('Feature list'), (safe.featureLists ?? []).map(list => [list.id, escapeHtml(list.name)] as const), shown?.featureListId)}</div><h3>${v.text(msgid('Resources'))}</h3><div class="xp-whm-detail-fields">${PLAN_RESOURCE_FIELDS.map(item => limitField(item, shown?.resources[item.key as keyof Plan['resources']])).join('')}</div><h3>${v.text(msgid('Service limits'))}</h3><div class="xp-whm-detail-fields">${PLAN_CAP_FIELDS.map(item => limitField(item, shown?.caps[item.key as keyof Plan['caps']])).join('')}${field(v, 'pending-plan-mailbox-quota', PLAN_QUOTA_FIELD.label, { type: 'number', ...(typeof shown?.defaultMailboxQuotaMb === 'number' ? { value: shown.defaultMailboxQuotaMb } : {}) })}${field(v, 'pending-plan-shell', msgid('Shell access'), { choices: [['none', msgid('No shell')], ['jailed', msgid('Jailed shell')]], ...(shown ? { value: shown.shell } : {}) })}</div>${actions(button(v, msgid('Save plan'), '', true, true))}`)
    const services = card(v, 'managed-services-unavailable', msgid('Managed services'), table(v, msgid('Managed services'), [msgid('Service'), msgid('Unit'), msgid('Version'), msgid('State'), msgid('Memory'), msgid('Action')], []) + actions(button(v, msgid('Reload service')) + button(v, msgid('Restart service'))))
    const content = route === '/whm/accounts/new' ? creation + renderApprovedWhmAccountCreateStatus(safe)
      : route === '/whm/accounts' ? renderApprovedWhmAccountBulkControls(safe) + accountList
      : route === '/whm/plans' ? planList + planEditor + renderApprovedWhmPlanSupplement(safe)
      : route === '/whm/services' ? services + renderApprovedWhmOperationsSupplement(safe) : renderApprovedWhmOperationsSupplement(safe)
    const title = route === '/whm/accounts/new' ? msgid('Create account') : route === '/whm/accounts' ? msgid('Accounts') : route === '/whm/plans' ? msgid('Plans') : route === '/whm/services' ? msgid('Services') : msgid('Firewall')
    return workspace(v, route, title, msgid('Approved components remain visible while the host operation is unavailable.'), content)
  }
  if (input.capabilityUnavailable && route === '/whm/dns') {
    const v: View = { props: savedLists(input), locale: input.locale ?? 'en', readOnly: true, root: false, text: copy => escapeHtml(translator(input.locale)(copy)) }
    // The first saved zone is selected, as the editor selects it once zones are read; rows and fields stay disabled.
    const { dnsZones: zones, accounts } = v.props, selected = zones?.[0]
    const ownerOf = (id: string | null) => id === null ? v.text(msgid('Unassigned (server)')) : value(v, accounts?.find(account => account.id === id)?.username)
    const zoneRows = (zones ?? []).map(zone => [renderLtrValue(zone.name), ownerOf(zone.accountId), renderLtrValue(String(zone.records.length)), renderLtrValue(String(zone.serial)), v.text(msgid('Saved'))])
    const recordRows = (selected?.records ?? []).map(record => [renderLtrValue(record.name), renderLtrValue(record.type), renderLtrValue(String(record.ttl)), renderLtrValue(record.content), record.priority === null ? '' : renderLtrValue(String(record.priority))])
    const editor = card(v, 'dns-editor-unavailable', msgid('Zones and records'), table(v, msgid('Zones'), [msgid('Zone'), msgid('Account'), msgid('Records'), msgid('Serial'), msgid('State')], zoneRows, zones ? msgid('No zones yet') : undefined) + `<div class="xp-whm-detail-fields">${pick(v, 'dns-pending-zone', msgid('Zone'), (zones ?? []).map(zone => [zone.name, escapeHtml(zone.name)] as const), selected?.name)}${pick(v, 'dns-pending-account', msgid('Account'), [['', v.text(msgid('Unassigned (server)'))], ...(accounts ?? []).map(account => [account.id, escapeHtml(account.username)] as const)], selected ? selected.accountId ?? '' : undefined)}${field(v, 'dns-pending-new-zone', msgid('New zone name'))}</div>${table(v, msgid('Records in the selected zone'), [msgid('Name'), msgid('Type'), 'TTL', msgid('Content'), msgid('Priority')], recordRows, selected ? msgid('No saved records. Add a record to this zone.') : undefined)}${actions(button(v, msgid('Add zone')) + button(v, msgid('Edit records')) + button(v, msgid('Save zone')) + button(v, msgid('Delete zone')))}`)
    // A new record starts as an A record at the TTL the zone renderer applies when none is given.
    const record = card(v, 'dns-record-unavailable', msgid('Add a record'), `<div class="xp-whm-detail-fields">${field(v, 'dns-pending-record-type', msgid('Record type'), { choices: ['A', 'AAAA', 'CNAME', 'MX', 'TXT', 'SRV', 'CAA'].map(type => [type, type] as const), value: 'A' })}${field(v, 'dns-pending-record-name', msgid('Name'))}${field(v, 'dns-pending-record-ttl', 'TTL', { type: 'number', value: services.DEFAULT_TTL })}${field(v, 'dns-pending-record-content', msgid('Content'))}${field(v, 'dns-pending-record-priority', msgid('Priority'), { type: 'number' })}${field(v, 'dns-pending-record-weight', msgid('Weight'), { type: 'number' })}${field(v, 'dns-pending-record-port', msgid('Port'), { type: 'number' })}</div>${actions(button(v, msgid('Clear')) + button(v, msgid('Add record')))}`)
    return workspace(v, route, msgid('DNS zones'), msgid('Zone files, SOA, history and provider health remain visible until this host qualifies DNS operations.'), editor + record + dnsComponents(v))
  }
  if (input.capabilityUnavailable && ['/whm/backups', '/whm/backups/restore'].includes(route)) {
    const backups = renderApprovedWhmBackups({ activeRoute: route, locale: input.locale, capabilityUnavailable: true })
    return (input.visibility?.principal ?? input.principal)?.kind === 'root' ? openFrameReads(backups) : backups
  }
  if (input.capabilityUnavailable && ['/whm/resellers', '/whm/resellers/privileges'].includes(route)) return renderApprovedWhmResellers({ activeRoute: route, locale: input.locale, capabilityUnavailable: true, ...savedLists(input) })
  const page = detailPages[route]
  if (!page) return undefined
  const locale = input.locale ?? 'en'
  const text = (copy: Copy): string => escapeHtml(translator(locale)(copy))
  const principal = input.visibility?.principal ?? input.principal
  const acls = input.visibility?.reseller?.acl ?? input.activeReseller?.acl ?? []
  const authorized = principal?.kind === 'root' || (principal?.kind === 'reseller' && (route === '/whm/preferences' || (page.acl !== undefined && acls.includes(page.acl))))
  if (!input.capabilityUnavailable && !authorized) return `<section class="xp-card" data-whm-detail-denied role="status"><h1>${text(page.title)}</h1><p>${text(msgid('This workspace requires an authorized administrator context.'))}</p></section>`
  const operationId = route === '/whm/plans/features' ? 'feature-list-crud'
    : ['/whm/services/web', '/whm/security/ssh', '/whm/server/setup'].includes(route) ? 'server-settings-edit' : undefined
  const missingOperation = operationId !== undefined && !input.catalog?.some(tool => tool.id === operationId && tool.status === 'verified')
  const readOnly = input.capabilityUnavailable === true || missingOperation
  // Read-only keeps the core-scoped stored records so closed fields show saved values; operations stay closed.
  const props: DetailProps = readOnly ? { ...input, activeRoute: route, capabilityUnavailable: true } : input
  return page.render({ props, locale, readOnly, root: principal?.kind === 'root', text }) + renderClassicSvcPanels(route, { locale, canRead: principal?.kind === 'root', canManage: tool => !readOnly && principal?.kind === 'root' && input.catalog?.some(item => item.id === tool && item.status === 'verified') === true })
}


/** Exports contain only the authorized page and public labels, never internal audit keys or raw details. */
export const renderWhmAuditExports = (props: WhmSurfaceProps): string => {
  const locale = props.locale ?? 'en'
  const rows = (props.auditEntries ?? []).map(entry => ({
    at: entry.at,
    actor: auditActorLabel(entry.actor),
    action: auditActionLabel(entry.action, locale, entry),
    target: auditTargetLabel(entry.target, locale),
    outcome: auditOutcomeLabel(entry.action, entry.outcome, locale),
  }))
  const csvCell = (raw: string): string => {
    const safe = /^[=+@\-\t\r]/.test(raw) ? `'${raw}` : raw
    return `"${safe.replaceAll('"', '""')}"`
  }
  const csv = [['UTC', 'Actor', 'Action', 'Target', 'Outcome'], ...rows.map(row => [row.at, row.actor, row.action, row.target, row.outcome])].map(row => row.map(csvCell).join(',')).join('\r\n')
  const csvHref = `data:text/csv;charset=utf-8,${encodeURIComponent('\uFEFF' + csv).replaceAll("'", '%27')}`
  const jsonHref = `data:application/json;charset=utf-8,${encodeURIComponent(JSON.stringify(rows, null, 2)).replaceAll("'", '%27')}`
  return `<div class="xp-whm-detail-actions" data-audit-export><a class="xp-btn" download="xpanel-audit-page.csv" href="${escapeHtml(csvHref)}">${translator(locale)('Export page CSV')}</a><a class="xp-btn" download="xpanel-audit-page.json" href="${escapeHtml(jsonHref)}">${translator(locale)('Export page JSON')}</a></div>`
}

export const renderWhmAuditSupplement = (props: WhmSurfaceProps): string => {
  const v: View = { props, locale: props.locale ?? 'en', readOnly: true, root: true, text: copy => escapeHtml(translator(props.locale)(copy)) }
  const entries = props.auditEntries ?? []
  const detail = entries.map(entry => `<details data-audit-entry-detail><summary>${escapeHtml(auditActionLabel(entry.action, props.locale ?? 'en', entry))} · ${renderLtrValue(formatDisplayDateTime(entry.at))}</summary>${facts(v, [[msgid('Actor'), auditActorLabel(entry.actor)], [msgid('Target'), auditTargetLabel(entry.target, props.locale ?? 'en')], [msgid('Outcome'), auditOutcomeLabel(entry.action, entry.outcome, props.locale ?? 'en')]])}</details>`).join('')
  return `${styles}<div class="xp-whm-detail-grid" data-audit-supplement><div class="xp-whm-detail-column">${card(v, 'audit-recorded-entry', msgid('Recorded entry'), detail || status(v, msgid('No entries match the current page.')))}</div><aside class="xp-whm-detail-column">${card(v, 'audit-config-generations', msgid('Config generations'), generationTable(v))}<p class="xp-help">${v.text(msgid('Exports and details contain this authorized page only. Older entries use the keyset page links.'))}</p></aside></div>`
}
